/** Basic */
export const Basic: Story = {
  name: "Basic",
  render: () => <Demo0 />,
  parameters: {
    docs: {
      description: { story: "Modal cơ bản." },
      source: { code: Demo0Source, language: 'tsx' },
    },
  },
  play: async ({ args, canvas, canvasElement, userEvent, step }) => {
    await step('Open and close the modal', async () => {
      await userEvent.click(canvas.getByRole('button', { name: 'Open Modal' }))
      const dialog = await screen.findByRole('dialog')
      await waitFor(() => expect(within(dialog).getByText('Basic Modal')).toBeVisible())
      await userEvent.click(within(dialog).getByRole('button', { name: 'OK' }))
      await waitFor(() => expect(screen.queryByRole('dialog')).toBeNull())
    })
  },
}

